using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type" in 9.0.
        // Preserve the old property name for compatibility with existing documents.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id property no longer includes the discriminator prefix.
        // EF8 stored id as "Blog|1"; EF9 stores just "1".
        // Preserve the old "Blog|" prefix format for existing documents.
        modelBuilder.Entity<Blog>().HasPartitionKey(e => e.Id);

        // Breaking change 3: Cosmos DB provider does not support indexes (never took effect).
        // HasIndex() now throws at model validation time in EF9 instead of being silently ignored.
        // REMOVED: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

