class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: EF9 Cosmos now uses role-based access (RBAC) by default and
        // the sync read-then-write pattern is unchanged, but raw SQL queries referencing
        // "Discriminator" must use the old property name we preserved in OnModelCreating.
        // If you have any raw SQL like:
        //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
        // it continues to work because we kept "Discriminator" as the property name above.
        // Without that fix, you'd need to change raw SQL to use c["$type"] = 'Blog'.

        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

